using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed class ResearchTools
{
    private readonly HttpClient _httpClient;
    private readonly List<NoteEntry> _notes = [];

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    [Description("Search the web for information on a given query. Returns a list of result snippets with titles and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        // Use DuckDuckGo Lite (HTML) which doesn't require an API key.
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("User-Agent", "ResearchAgent/1.0");

        using var response = await _httpClient.SendAsync(request, cancellationToken);
        response.EnsureSuccessStatusCode();

        var html = await response.Content.ReadAsStringAsync(cancellationToken);

        var results = ParseSearchResults(html);
        if (results.Count == 0)
        {
            return $"No results found for '{query}'.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Search results for '{query}':");
        sb.AppendLine();
        foreach (var (title, snippet, link) in results.Take(5))
        {
            sb.AppendLine($"**{title}**");
            if (!string.IsNullOrWhiteSpace(snippet))
                sb.AppendLine(snippet);
            if (!string.IsNullOrWhiteSpace(link))
                sb.AppendLine($"URL: {link}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Save a research note with a topic tag and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short topic tag for the note (e.g. 'definition', 'history', 'key-finding')")] string topic,
        [Description("The content of the note to save")] string content)
    {
        var entry = new NoteEntry(topic, content, DateTime.UtcNow);
        _notes.Add(entry);
        return $"Note saved under topic '{topic}'. Total notes: {_notes.Count}.";
    }

    [Description("Retrieve all saved research notes. Use this to review what has been gathered before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"Saved research notes ({_notes.Count} total):");
        sb.AppendLine();
        for (int i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"[{i + 1}] Topic: {note.Topic}");
            sb.AppendLine($"    {note.Content}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private static List<(string Title, string Snippet, string Url)> ParseSearchResults(string html)
    {
        var results = new List<(string, string, string)>();

        // DuckDuckGo Lite returns results in a table-based HTML format.
        // Extract links and surrounding text as snippets.
        var span = html.AsSpan();
        int pos = 0;

        while (pos < span.Length && results.Count < 10)
        {
            // Find result links — they appear as <a rel="nofollow" href="...">
            var linkMarker = "rel=\"nofollow\"";
            var idx = html.IndexOf(linkMarker, pos, StringComparison.OrdinalIgnoreCase);
            if (idx < 0) break;

            var hrefStart = html.IndexOf("href=\"", idx, StringComparison.OrdinalIgnoreCase);
            if (hrefStart < 0) break;
            hrefStart += 6;
            var hrefEnd = html.IndexOf('"', hrefStart);
            if (hrefEnd < 0) break;
            var url = html[hrefStart..hrefEnd];

            // Extract the link text as the title.
            var titleStart = html.IndexOf('>', hrefEnd);
            if (titleStart < 0) break;
            titleStart++;
            var titleEnd = html.IndexOf("</a>", titleStart, StringComparison.OrdinalIgnoreCase);
            if (titleEnd < 0) break;
            var title = StripHtml(html[titleStart..titleEnd]).Trim();

            // Look for a snippet in the next table cell.
            var snippet = "";
            var snippetSearch = html.IndexOf("<td", titleEnd, StringComparison.OrdinalIgnoreCase);
            if (snippetSearch >= 0)
            {
                var snippetStart = html.IndexOf('>', snippetSearch);
                if (snippetStart >= 0)
                {
                    snippetStart++;
                    var snippetEnd = html.IndexOf("</td>", snippetStart, StringComparison.OrdinalIgnoreCase);
                    if (snippetEnd >= 0)
                    {
                        snippet = StripHtml(html[snippetStart..snippetEnd]).Trim();
                    }
                }
            }

            pos = titleEnd + 4;

            if (!string.IsNullOrWhiteSpace(title) && url.StartsWith("http", StringComparison.OrdinalIgnoreCase))
            {
                title = WebUtility.HtmlDecode(title);
                snippet = WebUtility.HtmlDecode(snippet);
                results.Add((title, snippet, url));
            }
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder(html.Length);
        bool inTag = false;
        foreach (char c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) sb.Append(c);
        }
        return sb.ToString();
    }
}

public sealed record NoteEntry(string Topic, string Content, DateTime SavedAtUtc);

