using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Build the IChatClient through MEAI's OpenAI provider.
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// Create the research tools.
using var httpClient = new HttpClient();
var researchTools = new ResearchTools(httpClient);

// Register tools using AIFunctionFactory so the agent can call them.
var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

const string instructions = """
    You are a research agent. Your job is to research a topic thoroughly and produce a well-organized summary.

    Follow this workflow:
    1. Use SearchWebAsync to search for information on the topic. Run multiple searches with different
       query angles (e.g. definition, history, recent developments, key people, controversies).
    2. After each search, use SaveNote to record the most important findings with a descriptive topic tag.
    3. Once you have gathered enough information (at least 3-4 searches), use GetNotes to review all your
       notes.
    4. Write a comprehensive summary organized with clear headings and bullet points. Cite sources where
       possible.

    Be thorough but concise. Focus on factual, well-sourced information.
    """;

// Create the ChatClientAgent from Microsoft Agent Framework.
var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 Research Agent Ready        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic))
        continue;
    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"Researching: {topic}...");
    Console.ResetColor();
    Console.WriteLine();

    try
    {
        var runOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 4096,
            },
        };

        // Stream the agent's response so the user sees progress in real time.
        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session: null,
            options: runOptions))
        {
            if (!string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();

        // Show the notes that were collected.
        if (researchTools.Notes.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.Green;
            Console.WriteLine($"📝 {researchTools.Notes.Count} research note(s) were saved during this session.");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

