+{
+    Console.ForegroundColor = ConsoleColor.Cyan;
+    Console.Write("Research topic> ");
+    Console.ResetColor();
+
+    var topic = Console.ReadLine()?.Trim();
+    if (string.IsNullOrEmpty(topic))
+        continue;
+    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
+        break;
+
+    Console.WriteLine();
+    Console.ForegroundColor = ConsoleColor.DarkGray;
+    Console.WriteLine($"Researching: {topic}...");
+    Console.ResetColor();
+    Console.WriteLine();
+
+    try
+    {
+        var runOptions = new ChatClientAgentRunOptions
+        {
+            ChatOptions = new ChatOptions
+            {
+                Temperature = 0f,
+                MaxOutputTokens = 4096,
+            },
+        };
+
+        // Stream the agent's response so the user sees progress in real time.
+        await foreach (var update in agent.RunStreamingAsync(
+            $"Research the following topic and provide a comprehensive summary: {topic}",
+            session: null,
+            options: runOptions))
+        {
+            if (!string.IsNullOrEmpty(update.Text))
+            {
+                Console.Write(update.Text);
+            }
+        }
+
+        Console.WriteLine();
+        Console.WriteLine();
+
+        // Show the notes that were collected.
+        if (researchTools.Notes.Count > 0)
+        {
+            Console.ForegroundColor = ConsoleColor.Green;
+            Console.WriteLine($"📝 {researchTools.Notes.Count} research note(s) were saved during this session.");
+            Console.ResetColor();
+        }
+    }
+    catch (Exception ex)
+    {
+        Console.ForegroundColor = ConsoleColor.Red;
+        Console.WriteLine($"Error: {ex.Message}");
+        Console.ResetColor();
+    }
+
+    Console.WriteLine();
+}
